Local Ltac vl_rebuild_ctx m sp :=
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mx _) =>
  lazymatch goal with
  | OBJ : rw_cells _ mx (bv_unsigned sp + -64) ?ob, FRhi : rw_cells _ mx (bv_unsigned sp + -24) [C8 ?s1v; C8 ?s0v; C8 ?rav],
    LSV : rw_cells _ mx ?LST (C8 _ :: C8 _ :: ?lrest), WIN : bytes_at _ mx ?SP ?sbs, ST : stk _ mx ?lo _,
    MU : munch _ m mx, WM : wmono _ m mx, MI : mem_inv _ mx, SD : vl_side m _ ?shi _ _ _ |- _ =>
      let CTX := fresh "CTX" in
      assert (CTX : vl_ctx m mx sp s1v s0v rav LST SP sbs lrest lo shi ob)
        by (unfold vl_ctx; repeat (split; [eassumption|]); eassumption)
  end end.

(* [comment removed for export] *)
Local Ltac vl_call_incr sp LST it vp vl err SP pad7 sbs lrest lo shi OBJ LSV WIN ST SD MU WM CEIL SPAL LAL LO SHI SEPL SEPW WNZ LNZ :=
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    let ACc := fresh "ACc" in let SKc := fresh "SKc" in let AWc := fresh "AWc" in let ALc := fresh "ALc" in
    let AOc := fresh "AOc" in
    destruct (vl_side_now _ mc _ _ _ _ _ _ SD MU WM CEIL) as (ACc & SKc & AWc & ALc);
    assert (AOc : aobj mc (bv_unsigned sp + -64) SZ_TOKIT)
      by (eapply (aobj_stack mc lo shi); [exact SKc| clear - LO; lia| unfold SZ_TOKIT; clear; lia| unfold SZ_TOKIT; clear - SHI; lia]);
